      question: 'A worldbuilder is designing a fantasy realm where powerful, intelligent plant life is abundant and can be coaxed or magically grown into structures, tools, and even animated vehicles. However, metallic ores are extremely scarce and difficult to refine. What would be the most logical direction for this world\'s technological development?',
