      question: 'A worldbuilder is designing a society where magic allows individuals to instantly fabricate any non-magical tool or simple machine, requiring only focus and a small, easily replenishable magical residue. However, magic is limited to creating objects no more complex than a clockwork mechanism. What is the most likely long-term societal outcome of this magic-technology interaction?',
